// Regenerated by: mpd start <project>
// Add custom Moodle settings to config.php (the file that includes this one).

unset($CFG);
global $CFG;
$CFG = new stdClass();

define('MPD_PROJECT_NAME', '%%PROJECT%%');

$CFG->dbtype    = '%%DBTYPE%%';
$CFG->dblibrary = 'native';
$CFG->dbhost    = '%%DBHOST%%';
$CFG->dbname    = '%%PROJECT%%';
$CFG->dbuser    = '%%PROJECT%%';
$CFG->dbpass    = '%%PROJECT%%';
$CFG->prefix    = 'mdl_';
$CFG->dboptions = array(
    'dbpersist' => 0,
);

$CFG->wwwroot  = 'https://%%PROJECT%%.%%ZONE%%';

$CFG->dataroot = '/srv/data/%%PROJECT%%/dataroot';
$CFG->directorypermissions = 02777;

$CFG->sslproxy = true;

// Router (Moodle 5.0+). Caddy's php_fastcgi try_files chain ends at /r.php,
// so unknown URLs are dispatched through the router automatically. Telling
// Moodle the router is configured silences the environment check and lets
// it generate clean (no /r.php) URLs.
$CFG->routerconfigured = true;

$CFG->admin = 'admin';

$CFG->noreplyaddress = 'noreply@example.com';
$CFG->site_is_public = false;

// Mail: filled in by configure.sh from this project's own
// MPD_REQUIRE_SERVICES (in its mpd.env). List `mailpit` there and this is
// $CFG->smtphosts pointing at it — mailpit is a black hole: messages surface
// in its web UI and are never forwarded, so Moodle may send freely, and mpd
// starts the mailpit container on `mpd start`. Otherwise it is
// $CFG->noemailever = true, so a project can never send real mail by accident.
// Edit mpd.env and re-run `mpd start <project>` to change it.
%%MAIL_CONFIG%%

$CFG->debug = (E_ALL | 2048); // DEBUG_DEVELOPER - note that since Moodle 5.0 it is just E_ALL, but higher value here is ok.
$CFG->debugdisplay = 1;
$CFG->debug_developer_use_pretty_exceptions = 0; // Do not leak environment and source code!
$CFG->allowthemechangeonurl = 1;
$CFG->passwordpolicy = 0;
$CFG->cronclionly = 0;
$CFG->cron_keepalive = '0'; // Cron keep alive is problematic, better always avoid it.

$CFG->phpunit_dataroot  = '/srv/data/%%PROJECT%%/dataroot_phpunit';
$CFG->phpunit_prefix = 't_';
// Test files that some phpunit tests download, served by the exttests
// project (MPD_MOODLE_EXTTESTS). false skips those tests. To use another
// server, define both above the require line in config.php.
if (!defined('TEST_EXTERNAL_FILES_HTTP_URL')) {
    define('TEST_EXTERNAL_FILES_HTTP_URL', %%EXTTESTS_HTTP%%);
}
if (!defined('TEST_EXTERNAL_FILES_HTTPS_URL')) {
    define('TEST_EXTERNAL_FILES_HTTPS_URL', %%EXTTESTS_HTTPS%%);
}

// Behat: four independent test sites, so one can run a long suite while
// another is used to write a new test. Each has its own URL, tables,
// dataroot and failure dumps, and none of them knows about the others.
//   behat.%%PROJECT%%.%%ZONE%%   bht_  dataroot_behat   (tools: behat)
//   behat1.%%PROJECT%%.%%ZONE%%  bh1_  dataroot_behat1  (tools: behat1)
//   behat2.%%PROJECT%%.%%ZONE%%  bh2_  dataroot_behat2  (tools: behat2)
//   behat3.%%PROJECT%%.%%ZONE%%  bh3_  dataroot_behat3  (tools: behat3)
// A web request picks its site by host name. A CLI script picks it by
// MPD_BEHAT_INSTANCE, which the behat tools set. The prefixes must not start
// with one another: Moodle drops a test site by table prefix.
// 0 is the unnumbered site.
$mpdbehat = 0;
$mpdbehatweb = false;
if (PHP_SAPI === 'cli') {
    if (in_array(getenv('MPD_BEHAT_INSTANCE'), ['1', '2', '3'], true)) {
        $mpdbehat = (int)getenv('MPD_BEHAT_INSTANCE');
    }
} else {
    $mpdbehathost = strtolower(explode(':', $_SERVER['HTTP_HOST'] ?? '')[0]);
    if ($mpdbehathost === 'behat.%%PROJECT%%.%%ZONE%%') {
        $mpdbehatweb = true;
    } else if ($mpdbehathost === 'behat1.%%PROJECT%%.%%ZONE%%') {
        $mpdbehat = 1;
        $mpdbehatweb = true;
    } else if ($mpdbehathost === 'behat2.%%PROJECT%%.%%ZONE%%') {
        $mpdbehat = 2;
        $mpdbehatweb = true;
    } else if ($mpdbehathost === 'behat3.%%PROJECT%%.%%ZONE%%') {
        $mpdbehat = 3;
        $mpdbehatweb = true;
    }
    unset($mpdbehathost);
}
if ($mpdbehat === 0) {
    $CFG->behat_wwwroot   = 'https://behat.%%PROJECT%%.%%ZONE%%';
    $CFG->behat_dataroot  = '/srv/data/%%PROJECT%%/dataroot_behat';
    $CFG->behat_prefix    = 'bht_';
} else {
    $CFG->behat_wwwroot   = 'https://behat' . $mpdbehat . '.%%PROJECT%%.%%ZONE%%';
    $CFG->behat_dataroot  = '/srv/data/%%PROJECT%%/dataroot_behat' . $mpdbehat;
    $CFG->behat_prefix    = 'bh' . $mpdbehat . '_';
}

// Screenshots + HTML dumps of failed steps. Kept outside behat_dataroot on
// purpose: `behat --init` wipes that tree, which would take the evidence
// from the previous run with it.
$CFG->behat_faildump_path = '/srv/data/%%PROJECT%%/behat_faildump' . ($mpdbehat === 0 ? '' : $mpdbehat);

// One log per behat site: behat_error.log, behat1_error.log, behat2_error.log
// and behat3_error.log,
// in /srv/data/%%PROJECT%%/. The behat_mpd_log context, which ships with mpd,
// writes the start and end of every feature and scenario and each failed
// step into it, and sends the runner's PHP errors there. The PHP errors of
// the site's web requests are sent there too, so they stay out of the
// development site's php_error.log and can be matched to a scenario.
define('MPD_BEHAT_LOG', '/srv/data/%%PROJECT%%/behat' . ($mpdbehat === 0 ? '' : $mpdbehat) . '_error.log');
if ($mpdbehatweb) {
    ini_set('error_log', MPD_BEHAT_LOG);
}
// Only the behat tools that write behat.yml get the context. Moodle's own
// phpunit tests of that writer count the suites and fail otherwise.
if (defined('BEHAT_UTIL')) {
    $CFG->behat_config = [
        'default' => [
            'suites' => [
                'default' => [
                    // A key far past Moodle's own list: its merge would let a
                    // low one replace a core context.
                    'contexts' => [100000 => 'behat_mpd_log'],
                ],
            ],
            'extensions' => [
                'Moodle\\BehatExtension' => [
                    'steps_definitions' => [
                        'behat_mpd_log' => '/opt/mpd/assets/vm/project_types/moodle/behat/behat_mpd_log.php',
                    ],
                ],
            ],
        ],
    ];
}
unset($mpdbehat, $mpdbehatweb);

// Behat drives Debian's Chromium through chromedriver on this VM, which
// the behat tool starts when it is needed. The ports are the ones in
// scripts/chromedriver.sh. Without an explicit profile Moodle/Mink defaults
// to firefox, so both profiles pin chrome, the name Chromium answers to.
//
//   default  headless, for normal runs. Headless browsers do not compete
//            for window focus, so any number of runs can share the VM.
//   headed   a visible browser on the desktop, to watch a test you are
//            debugging: behat --profile=headed <feature>
//
// acceptInsecureCerts: the Behat site is served over HTTPS with mpd's
// private CA. Without it a browser that does not trust that CA stops every
// page load at a "your connection is not private" page. It is the standard
// W3C capability for testing against a local certificate.
$CFG->behat_profiles = [
    'default' => [
        'browser' => 'chrome',
        'wd_host' => 'http://localhost:9515',
        'capabilities' => [
            'extra_capabilities' => [
                'acceptInsecureCerts' => true,
                // Moodle merges this with its own Chrome arguments.
                'goog:chromeOptions' => ['args' => ['headless=new']],
            ],
        ],
    ],
    'headed' => [
        'browser' => 'chrome',
        'wd_host' => 'http://localhost:9516',
        'capabilities' => [
            'extra_capabilities' => [
                'acceptInsecureCerts' => true,
            ],
        ],
    ],
];

// VM-wide overrides shared by every Moodle project (e.g. the Cloudflare
// quick tunnel wwwroot). Developer-owned; edit that file, not this one.
if (is_readable('/var/lib/mpd/moodle/config-global.php')) {
    require '/var/lib/mpd/moodle/config-global.php';
